// Hand-written `@nestjs/axios` stub, in the real library's shape: every verb is
// `<T, R = AxiosResponse<T>>(...) => Observable<R>`.
//
// The type argument a call writes is the payload, the envelope around it is
// `AxiosResponse`, and the envelope arrives inside an `Observable` because Nest
// hands back the request rather than its result. The stub used to answer
// `{ data: AxiosResponse<T> }`, which got both of those wrong at once — no
// delivery wrapper, and `.data` holding the response instead of the payload.
// It is the response type the call's own type argument names that makes the
// shape at the far end readable, and that part was always right.
//
// `AxiosResponse` is imported rather than declared here, because `@nestjs/axios`
// does not export it: it belongs to `axios`, and a stub that hands out a name
// its library never exported is a fixture testing the stub.
//
// All five verbs are written down even where one fixture uses two of them. The
// suite used to carry a two-verb variant beside this one, and the fixture that
// wrote `http.delete` was reading a method its own stub did not declare — a
// declaration gap is not the same freedom as declaring less, because the source
// written against it no longer says anything a compiler could check.

import type { AxiosResponse } from 'axios';
import type { Observable } from 'rxjs';

export declare class HttpService {
  get<T = unknown, R = AxiosResponse<T>>(url: string, config?: unknown): Observable<R>;
  post<T = unknown, R = AxiosResponse<T>>(url: string, body?: unknown, config?: unknown): Observable<R>;
  put<T = unknown, R = AxiosResponse<T>>(url: string, body?: unknown, config?: unknown): Observable<R>;
  patch<T = unknown, R = AxiosResponse<T>>(url: string, body?: unknown, config?: unknown): Observable<R>;
  delete<T = unknown, R = AxiosResponse<T>>(url: string, config?: unknown): Observable<R>;
}
